blocks.body:
{
    "level": "A2",
    "intro": "У цій темі ти навчишся правильно утворювати та вживати <strong>comparative<\/strong> (вищий ступінь) і <strong>superlative<\/strong> (найвищий ступінь) прикметників і прислівників.",
    "rules": [
        {
            "label": "Base form",
            "color": "emerald",
            "text": "Опис без порівняння:",
            "example": "This road is narrow."
        },
        {
            "label": "Comparative",
            "color": "blue",
            "text": "Порівняння двох речей з <em>than<\/em>:",
            "example": "This road is narrower than that one."
        },
        {
            "label": "Superlative",
            "color": "rose",
            "text": "Виділення одного з групи з <em>the<\/em>:",
            "example": "This is the narrowest street in town."
        }
    ]
}

{
    "title": "1. Короткі слова (1–2 склади)",
    "intro": "Для коротких прикметників додаємо закінчення <code class=\"font-mono text-xs\">-er<\/code> \/ <code class=\"font-mono text-xs\">-est<\/code>:",
    "items": [
        {
            "label": "Загальне правило",
            "title": "-er \/ -est",
            "subtitle": "fast → faster → the fastest"
        },
        {
            "label": "Закінчення на -y",
            "title": "-ier \/ -iest",
            "subtitle": "happy → happier → the happiest"
        },
        {
            "label": "Подвоєння",
            "title": "big → bigger",
            "subtitle": "Якщо: приголосний + голосний + приголосний"
        },
        {
            "label": "Закінчення на -e",
            "title": "-r \/ -st",
            "subtitle": "large → larger → the largest"
        }
    ]
}

{
    "title": "2. Довгі слова й прислівники",
    "sections": [
        {
            "label": "More \/ Most",
            "color": "emerald",
            "description": "Прикметники з 3+ складами та більшість прислівників використовують <strong>more \/ most<\/strong>.",
            "examples": [
                {
                    "en": "interesting → more interesting → the most interesting",
                    "ua": "цікавий"
                },
                {
                    "en": "quickly → more quickly → the most quickly",
                    "ua": "швидко"
                }
            ]
        },
        {
            "label": "Less \/ Least",
            "color": "rose",
            "description": "Для протилежного значення використовуємо <strong>less \/ least<\/strong>.",
            "examples": [
                {
                    "en": "dangerous → less dangerous → the least dangerous",
                    "ua": "небезпечний"
                }
            ]
        },
        {
            "label": "Двоскладові слова",
            "color": "sky",
            "description": "Деякі допускають обидві форми (закінчення на -y, -ow, -er):",
            "examples": [
                {
                    "en": "shallow → shallower \/ more shallow",
                    "ua": "мілкий"
                },
                {
                    "en": "clever → cleverer \/ more clever",
                    "ua": "розумний"
                }
            ]
        }
    ]
}

{
    "title": "3. Неправильні форми",
    "intro": "Деякі прикметники та прислівники мають особливі форми ступенів порівняння:",
    "rows": [
        {
            "en": "good \/ well",
            "ua": "хороший \/ добре",
            "note": "better → the best"
        },
        {
            "en": "bad \/ badly",
            "ua": "поганий \/ погано",
            "note": "worse → the worst"
        },
        {
            "en": "far",
            "ua": "далекий \/ далеко",
            "note": "farther\/further → the farthest\/furthest"
        },
        {
            "en": "little (amount)",
            "ua": "мало",
            "note": "less → the least"
        },
        {
            "en": "many \/ much",
            "ua": "багато",
            "note": "more → the most"
        }
    ],
    "warning": "💡 <em>Further<\/em> частіше про «додатковий» або «далі в часі», а <em>farther<\/em> — про фізичну відстань."
}

{
    "title": "4. Підсилення та послаблення",
    "sections": [
        {
            "label": "Підсилення comparative",
            "color": "emerald",
            "description": "Використовуй <strong>much \/ way \/ a lot \/ far<\/strong> перед comparative:",
            "examples": [
                {
                    "en": "This is much better than before.",
                    "ua": "Це набагато краще, ніж раніше."
                },
                {
                    "en": "He runs way faster than me.",
                    "ua": "Він бігає набагато швидше за мене."
                }
            ]
        },
        {
            "label": "Підсилення superlative",
            "color": "blue",
            "description": "Використовуй <strong>by far \/ easily<\/strong> перед superlative:",
            "examples": [
                {
                    "en": "She is by far the best student.",
                    "ua": "Вона безперечно найкраща студентка."
                }
            ]
        },
        {
            "label": "Послаблення",
            "color": "sky",
            "description": "Використовуй <strong>slightly \/ a bit \/ a little<\/strong> для незначної різниці:",
            "examples": [
                {
                    "en": "This is slightly cheaper.",
                    "ua": "Це трохи дешевше."
                }
            ]
        }
    ]
}

{
    "title": "5. Конструкції порівняння",
    "sections": [
        {
            "label": "As ... as",
            "color": "emerald",
            "description": "Для рівності використовуй <strong>as + adjective\/adverb + as<\/strong>:",
            "examples": [
                {
                    "en": "She is as tall as her brother.",
                    "ua": "Вона така ж висока, як її брат."
                },
                {
                    "en": "He runs as fast as me.",
                    "ua": "Він бігає так само швидко, як я."
                }
            ]
        },
        {
            "label": "Not as\/so ... as",
            "color": "rose",
            "description": "Для нерівності використовуй <strong>not as\/so + adjective + as<\/strong>:",
            "examples": [
                {
                    "en": "This book is not as interesting as that one.",
                    "ua": "Ця книга не така цікава, як та."
                }
            ]
        },
        {
            "label": "The + superlative + in\/of",
            "color": "sky",
            "description": "Для виділення з групи:",
            "examples": [
                {
                    "en": "He is the tallest in the class.",
                    "ua": "Він найвищий у класі."
                },
                {
                    "en": "This is the most useful of all.",
                    "ua": "Це найкорисніше з усіх."
                }
            ]
        }
    ]
}

{
    "title": "6. Типові помилки україномовних",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Подвійні маркери порівняння.",
            "wrong": "more better \/ the most fastest",
            "right": "✅ <span class=\"font-mono\">better \/ the fastest<\/span>"
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Пропуск <strong>the<\/strong> перед superlative.",
            "wrong": "He is tallest in the class.",
            "right": "✅ <span class=\"font-mono\">He is the tallest in the class.<\/span>"
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Неправильне узгодження з <strong>than<\/strong>.",
            "wrong": "My car is more reliable than your.",
            "right": "✅ <span class=\"font-mono\">My car is more reliable than yours.<\/span>"
        }
    ]
}

{
    "title": "Продовжуй навчання",
    "items": [
        {
            "label": "Degrees of Comparison — Ступені порівняння",
            "current": true
        },
        {
            "label": "Comparative vs Superlative — Вибір форми",
            "current": false
        },
        {
            "label": "Equality Comparison — as ... as / not as ... as",
            "current": false
        },
        {
            "label": "Adjectives vs Adverbs — Прикметники й прислівники",
            "current": false
        }
    ]
}

{
    "level": "A2–B1",
    "intro": "У цій темі ти навчишся <strong>правильно вибирати між comparative та superlative<\/strong> залежно від контексту та кількості об'єктів порівняння.",
    "rules": [
        {
            "label": "COMPARATIVE",
            "color": "blue",
            "text": "<strong>Порівняння двох<\/strong> — використовуй з <em>than<\/em>:",
            "example": "This car is faster than that one."
        },
        {
            "label": "SUPERLATIVE",
            "color": "rose",
            "text": "<strong>Виділення з групи<\/strong> — використовуй з <em>the<\/em>:",
            "example": "This is the fastest car in the race."
        },
        {
            "label": "KEY DIFFERENCE",
            "color": "emerald",
            "text": "<strong>Кількість об'єктів<\/strong> визначає вибір:",
            "example": "2 objects → comparative; 3+ objects → superlative"
        }
    ]
}

{
    "title": "1. Основна різниця у вживанні",
    "intro": "Головна відмінність між comparative та superlative полягає в <strong>кількості об'єктів<\/strong>, що порівнюються:",
    "rows": [
        {
            "en": "Comparative",
            "ua": "Вищий ступінь",
            "note": "Порівняння ДВОХ предметів\/осіб → -er \/ more ... than"
        },
        {
            "en": "Superlative",
            "ua": "Найвищий ступінь",
            "note": "Виділення ОДНОГО з групи (3+) → -est \/ the most"
        },
        {
            "en": "Tom is taller than John.",
            "ua": "Том вищий за Джона.",
            "note": "✓ comparative — два об'єкти (Tom і John)"
        },
        {
            "en": "Tom is the tallest in the class.",
            "ua": "Том найвищий у класі.",
            "note": "✓ superlative — один з групи (весь клас)"
        }
    ],
    "warning": "💡 Запам'ятай: <strong>два об'єкти = comparative<\/strong>, <strong>три+ об'єкти = superlative<\/strong>."
}

{
    "title": "2. Коли використовувати Comparative",
    "sections": [
        {
            "label": "Пряме порівняння двох",
            "color": "blue",
            "description": "Використовуй <strong>comparative<\/strong>, коли порівнюєш <strong>дві конкретні речі<\/strong>:",
            "examples": [
                {
                    "en": "My house is bigger than your house.",
                    "ua": "Мій будинок більший за твій будинок."
                },
                {
                    "en": "She is more intelligent than her brother.",
                    "ua": "Вона розумніша за свого брата."
                },
                {
                    "en": "Today is colder than yesterday.",
                    "ua": "Сьогодні холодніше, ніж вчора."
                }
            ]
        },
        {
            "label": "Порівняння з \"than\"",
            "color": "sky",
            "description": "Маркер <strong>than<\/strong> майже завжди вказує на потребу в comparative:",
            "examples": [
                {
                    "en": "This book is more interesting than the previous one.",
                    "ua": "Ця книга цікавіша за попередню."
                },
                {
                    "en": "He runs faster than anyone I know.",
                    "ua": "Він бігає швидше за всіх, кого я знаю."
                },
                {
                    "en": "It's better than I expected.",
                    "ua": "Це краще, ніж я очікував."
                }
            ]
        },
        {
            "label": "Загальне порівняння",
            "color": "emerald",
            "description": "Навіть без явного \"than\", коли мається на увазі порівняння двох станів:",
            "examples": [
                {
                    "en": "I feel better today. (ніж вчора)",
                    "ua": "Я почуваюся краще сьогодні."
                },
                {
                    "en": "Can you speak louder? (ніж зараз)",
                    "ua": "Можеш говорити голосніше?"
                },
                {
                    "en": "This method is more effective. (ніж інший)",
                    "ua": "Цей метод ефективніший."
                }
            ]
        }
    ]
}

{
    "title": "3. Коли використовувати Superlative",
    "sections": [
        {
            "label": "Виділення з групи",
            "color": "rose",
            "description": "Використовуй <strong>superlative<\/strong>, коли виділяєш <strong>один об'єкт серед багатьох<\/strong>:",
            "examples": [
                {
                    "en": "He is the tallest student in the class.",
                    "ua": "Він найвищий студент у класі."
                },
                {
                    "en": "This is the most expensive car in the showroom.",
                    "ua": "Це найдорожча машина в салоні."
                },
                {
                    "en": "She is the smartest person I know.",
                    "ua": "Вона найрозумніша людина, яку я знаю."
                }
            ]
        },
        {
            "label": "Використання \"the\"",
            "color": "amber",
            "description": "Маркер <strong>the<\/strong> перед прикметником майже завжди вказує на superlative:",
            "examples": [
                {
                    "en": "Mount Everest is the highest mountain in the world.",
                    "ua": "Еверест — найвища гора в світі."
                },
                {
                    "en": "This is the best pizza I've ever had.",
                    "ua": "Це найкраща піца, яку я коли-небудь їв."
                },
                {
                    "en": "She chose the cheapest option.",
                    "ua": "Вона обрала найдешевший варіант."
                }
            ]
        },
        {
            "label": "З прийменниками in\/of",
            "color": "sky",
            "description": "Superlative часто йде з <strong>in<\/strong> (місце\/група) або <strong>of<\/strong> (набір):",
            "examples": [
                {
                    "en": "He is the fastest runner in the team.",
                    "ua": "Він найшвидший бігун у команді."
                },
                {
                    "en": "This is the oldest of all the buildings.",
                    "ua": "Це найстаріша з усіх будівель."
                },
                {
                    "en": "She is the youngest in her family.",
                    "ua": "Вона наймолодша у своїй родині."
                }
            ]
        }
    ]
}

{
    "title": "4. Візуальне правило вибору",
    "intro": "Простий алгоритм для вибору між comparative та superlative:",
    "items": [
        {
            "label": "Крок 1",
            "title": "Скільки об'єктів?",
            "subtitle": "2 об'єкти → Comparative; 3+ об'єкти → Superlative"
        },
        {
            "label": "Крок 2",
            "title": "Шукай маркери",
            "subtitle": "than = Comparative; the = Superlative"
        },
        {
            "label": "Крок 3",
            "title": "Контекст порівняння",
            "subtitle": "Пряме порівняння → Comparative; Виділення → Superlative"
        },
        {
            "label": "Крок 4",
            "title": "Перевір прийменники",
            "subtitle": "in\/of після прикметника → ймовірно Superlative"
        }
    ]
}

{
    "title": "5. Порівняння конструкцій",
    "intro": "Паралельні приклади для кращого розуміння різниці:",
    "rows": [
        {
            "en": "Paris is bigger than Lyon.",
            "ua": "Париж більший за Ліон.",
            "note": "✓ comparative — два міста"
        },
        {
            "en": "Paris is the biggest city in France.",
            "ua": "Париж — найбільше місто у Франції.",
            "note": "✓ superlative — одне з багатьох міст"
        },
        {
            "en": "This exam was harder than the last one.",
            "ua": "Цей іспит був складніший за попередній.",
            "note": "✓ comparative — два іспити"
        },
        {
            "en": "This was the hardest exam of the year.",
            "ua": "Це був найскладніший іспит року.",
            "note": "✓ superlative — один з усіх іспитів року"
        },
        {
            "en": "She is more experienced than me.",
            "ua": "Вона досвідченіша за мене.",
            "note": "✓ comparative — дві особи"
        },
        {
            "en": "She is the most experienced in our team.",
            "ua": "Вона найдосвідченіша в нашій команді.",
            "note": "✓ superlative — одна з команди"
        }
    ],
    "warning": "💡 Зверни увагу на маркери: <strong>than<\/strong> для comparative, <strong>the<\/strong> для superlative."
}

{
    "title": "6. Типові помилки україномовних",
    "sections": [
        {
            "label": "Помилка 1: Плутанина з \"the\"",
            "color": "rose",
            "description": "Використання <strong>the<\/strong> з comparative або його пропуск із superlative:",
            "examples": [
                {
                    "en": "❌ He is the taller than me. → ✓ He is taller than me.",
                    "ua": "ПОМИЛКА: the з comparative"
                },
                {
                    "en": "❌ She is most beautiful girl. → ✓ She is the most beautiful girl.",
                    "ua": "ПОМИЛКА: пропуск the"
                },
                {
                    "en": "❌ This is more better. → ✓ This is better.",
                    "ua": "ПОМИЛКА: подвійний маркер"
                }
            ]
        },
        {
            "label": "Помилка 2: Неправильний вибір",
            "color": "amber",
            "description": "Використання comparative замість superlative і навпаки:",
            "examples": [
                {
                    "en": "❌ She is the taller of two sisters. → ✓ She is the taller of the two.",
                    "ua": "Два об'єкти — можна the taller"
                },
                {
                    "en": "❌ He is taller in the class. → ✓ He is the tallest in the class.",
                    "ua": "Група — потрібен superlative"
                },
                {
                    "en": "❌ This is the better than that. → ✓ This is better than that.",
                    "ua": "Порівняння — тільки comparative"
                }
            ]
        },
        {
            "label": "Помилка 3: Пропуск \"than\"",
            "color": "sky",
            "description": "Забування <strong>than<\/strong> після comparative при порівнянні:",
            "examples": [
                {
                    "en": "❌ My car is faster your car. → ✓ My car is faster than yours.",
                    "ua": "ПОМИЛКА: пропуск than"
                },
                {
                    "en": "❌ She is more intelligent him. → ✓ She is more intelligent than him.",
                    "ua": "ПОМИЛКА: пропуск than"
                }
            ]
        }
    ]
}

{
    "title": "7. Особливі випадки",
    "sections": [
        {
            "label": "Порівняння двох: може бути superlative!",
            "color": "emerald",
            "description": "З <strong>of the two<\/strong> можна використовувати superlative для підкреслення:",
            "examples": [
                {
                    "en": "She is the taller of the two sisters.",
                    "ua": "Вона вища з двох сестер. (формально)"
                },
                {
                    "en": "She is taller than her sister.",
                    "ua": "Вона вища за свою сестру. (звичайно)"
                },
                {
                    "en": "This is the better of the two options.",
                    "ua": "Це кращий з двох варіантів."
                }
            ]
        },
        {
            "label": "Порівняння з собою",
            "color": "blue",
            "description": "Comparative використовується для порівняння <strong>різних станів однієї речі<\/strong>:",
            "examples": [
                {
                    "en": "The weather is getting colder.",
                    "ua": "Погода стає холоднішою."
                },
                {
                    "en": "I'm feeling better now.",
                    "ua": "Я почуваюся краще зараз."
                },
                {
                    "en": "Life is more complicated than before.",
                    "ua": "Життя складніше, ніж раніше."
                }
            ]
        },
        {
            "label": "Абсолютний superlative",
            "color": "rose",
            "description": "Іноді superlative вживається <strong>без групи<\/strong> для підкреслення:",
            "examples": [
                {
                    "en": "You are the best! (взагалі, не в групі)",
                    "ua": "Ти найкращий!"
                },
                {
                    "en": "This is the worst! (емоційно)",
                    "ua": "Це найгірше!"
                },
                {
                    "en": "Have a most wonderful day! (дуже ввічливо)",
                    "ua": "Гарного дня!"
                }
            ]
        }
    ]
}

{
    "title": "8. Контрольний список для перевірки",
    "items": [
        {
            "label": "Перевірка 1",
            "color": "emerald",
            "title": "Скільки об'єктів порівнюється?",
            "wrong": "Два об'єкти?",
            "right": "→ Використовуй <strong>comparative<\/strong>"
        },
        {
            "label": "Перевірка 2",
            "color": "blue",
            "title": "Є слово \"than\" у реченні?",
            "wrong": "Так, є \"than\"",
            "right": "→ Використовуй <strong>comparative<\/strong>"
        },
        {
            "label": "Перевірка 3",
